import echartsFrom from '@/components/echarts/index';
import cardsData from '@/components/cards/cards';
import echartsNew from '@/components/echartsNew/index';
import { wechatQrcodeStatistic as _wechatQrcodeStatistic } from '@/api/marketing';
import { formatDate } from '@/utils/validate';
import Setting from '@/setting';
export default {
  name: 'marketing_channelStatistic',
  components: {
    cardsData: cardsData,
    echartsNew: echartsNew,
    echartsFrom: echartsFrom
  },
  data: function data() {
    return {
      roterPre: Setting.roterPre,
      timeVal: [],
      style: {
        height: '400px'
      },
      infoList: {},
      infoList2: {},
      echartLeft: true,
      echartRight: false,
      loading: false,
      loading2: false,
      fromList: {
        title: '选择时间',
        custom: true,
        fromTxt: [{
          text: '全部',
          val: ''
        }, {
          text: '今天',
          val: 'today'
        }, {
          text: '本周',
          val: 'week'
        }, {
          text: '本月',
          val: 'month'
        }, {
          text: '本季度',
          val: 'quarter'
        }, {
          text: '本年',
          val: 'year'
        }]
      },
      formValidate: {
        time: ''
      },
      cardLists: [{
        col: 6,
        count: 0,
        name: '昨日新增关注',
        className: 'md-rose'
      }, {
        col: 6,
        count: 0,
        name: '昨日参与',
        className: 'ios-speedometer-outline'
      }, {
        col: 6,
        count: 0,
        name: '总关注',
        className: 'ios-speedometer-outline'
      }, {
        col: 6,
        count: 0,
        name: '参与总人数',
        className: 'md-rose'
      }],
      optionData: {},
      spinShow: false,
      options: this.$timeOptions,
      columns: [{
        title: '序号',
        type: 'index',
        width: 60,
        align: 'center'
      }, {
        title: '来源',
        key: 'name',
        minWidth: 80,
        align: 'center'
      }, {
        title: '金额',
        width: 180,
        key: 'value',
        align: 'center'
      }, {
        title: '占比率',
        slot: 'percent',
        minWidth: 100,
        align: 'center'
      }]
    };
  },
  created: function created() {
    this.id = this.$route.query.id;
    var end = new Date();
    var start = new Date();
    start.setTime(start.setTime(new Date(new Date().getFullYear(), new Date().getMonth(), new Date().getDate() - 29)));
    this.timeVal = [start, end];
    this.formValidate.time = formatDate(start, 'yyyy/MM/dd') + '-' + formatDate(end, 'yyyy/MM/dd');
    this.wechatQrcodeStatistic();
  },
  methods: {
    wechatQrcodeStatistic: function wechatQrcodeStatistic() {
      var _this = this;
      _wechatQrcodeStatistic(this.id, this.formValidate).then(function (res) {
        var arr = ['y_follow', 'y_scan', 'all_follow', 'all_scan'];
        _this.cardLists.map(function (i, index) {
          i.count = res.data[arr[index]];
        });
        _this.getTrend(res.data.trend.series, res.data.trend.xAxis);
      });
    },
    timeG: function timeG(dd) {
      var d = new Date(dd);
      var datetime = d.getFullYear() + '-' + (d.getMonth() + 1) + '-' + d.getDate() + ' ' + d.getHours() + ':' + d.getMinutes() + ':' + d.getSeconds();
      return datetime;
    },
    // 具体日期
    onchangeTime: function onchangeTime(e) {
      this.timeVal = e;
      this.formValidate.time = this.timeVal[0] ? this.timeVal.join('-') : "";
      this.name = this.formValidate.time;
      this.wechatQrcodeStatistic();
    },
    // 统计图
    getTrend: function getTrend(seriesData, xAxisData) {
      this.spinShow = true;
      var legend = seriesData.map(function (item) {
        return item.name;
      });
      var xAxis = xAxisData;
      var col = ['#5B8FF9', '#5AD8A6', '#FFAB2B', '#5D7092'];
      var series = [];
      seriesData.map(function (item, index) {
        series.push({
          name: item.name,
          type: 'line',
          data: item.data,
          itemStyle: {
            normal: {
              color: col[index]
            }
          },
          smooth: 0
        });
      });
      this.optionData = {
        tooltip: {
          trigger: 'axis',
          axisPointer: {
            type: 'cross',
            label: {
              backgroundColor: '#6a7985'
            }
          }
        },
        legend: {
          x: 'center',
          data: legend
        },
        grid: {
          left: '3%',
          right: '4%',
          bottom: '3%',
          containLabel: true
        },
        toolbox: {
          feature: {
            saveAsImage: {}
          }
        },
        xAxis: {
          type: 'category',
          boundaryGap: true,
          axisLabel: {
            interval: 0,
            rotate: 40,
            textStyle: {
              color: '#000000'
            }
          },
          data: xAxis
        },
        yAxis: {
          type: 'value',
          axisLine: {
            show: false
          },
          axisTick: {
            show: false
          },
          axisLabel: {
            textStyle: {
              color: '#7F8B9C'
            }
          },
          splitLine: {
            show: true,
            lineStyle: {
              color: '#F5F7F9'
            }
          }
        },
        series: series
      };
      this.spinShow = false;
    }
  }
};
